class ParentClass():
    def __init__(self, a, b):
        self.a = a
        self.b = b


class ChildClass(ParentClass):
    def __init__(self, a, b, c):
        super().__init__(a, b) # 在第一行调用父类__init__
        self.c = c


obj = ChildClass(1, 2, 3)
print(obj.a)
print(obj.b)
print(obj.c)

class ParentClass():
    def __init__(self, a, b):
        self.a = a
        self.b = b


class ChildClass(ParentClass):
    def __init__(self, a, b, c):
        self.c = c
        super().__init__(a, b) # 非第一行调用父类__init__


obj = ChildClass(1, 2, 3)
print(obj.a)
print(obj.b)
print(obj.c)

class Vehicle:
    def __init__(self, make, color, model):
        self.make = make
        self.color = color
        self.model = model

    def printDetails(self):
        print("制造商:", self.make)
        print("颜色:", self.color)
        print("型号:", self.model)


class Car(Vehicle):
    def __init__(self, make, color, model, doors):
        Vehicle.__init__(self, make, color, model) # 上一课方法
        self.doors = doors

    def printCarDetails(self):
        self.printDetails()
        print("车门数:", self.doors)


obj1 = Car("比亚迪", "红色", "高配版", 4)
obj1.printCarDetails()

